'use strict'

const { createSecureServer } = require('node:http2')
const { once } = require('node:events')
const pem = require('@metcoder95/https-pem')
const { Client } = require('/tmp/cxbench-undici/85b35e7791-none')

process.on('uncaughtException', (err) => {
  console.log('[UNCAUGHT EXCEPTION]', err.stack)
  process.exit(1)
})

async function main () {
  const server = createSecureServer(await pem.generate({ opts: { keySize: 2048 } }))
  server.on('error', () => {})
  server.on('session', (session) => {
    session.on('error', () => {})
    session.socket?.on('error', () => {})
  })

  let sockets = []
  server.on('secureConnection', (socket) => {
    sockets.push(socket)
    socket.on('error', () => {})
  })

  server.on('stream', (stream) => {
    stream.on('error', () => {})
    stream.respond({ ':status': 200, 'content-type': 'application/octet-stream' })
    stream.write(Buffer.alloc(1024))
    // never end: long download
  })

  await once(server.listen(0), 'listening')

  const client = new Client(`https://localhost:${server.address().port}`, {
    connect: { rejectUnauthorized: false },
    allowH2: true
  })

  const results = []
  for (let i = 0; i < 3; i++) {
    results.push(client.request({
      path: '/' + i,
      method: 'GET',
      signal: AbortSignal.timeout(200)
    }).then(({ body }) => {
      body.on('error', (e) => console.log('body error', e.code))
      body.resume()
      return once(body, 'close')
    }).catch((e) => console.log('req error', e.code || e.message)))
  }

  setTimeout(() => {
    console.log('server: ending sockets (FIN)')
    for (const s of sockets) s.end()
  }, 250)

  await Promise.all(results)
  await new Promise((resolve) => setTimeout(resolve, 1000))
  console.log('done, no uncaught')
  await client.close().catch(() => {})
  server.close()
}

main()

