})

const ROUNDS = Number(process.argv[2] || 50)

async function main () {
  const server = createSecureServer(await pem.generate({ opts: { keySize: 2048 } }))
  server.on('error', () => {})
  const sessions = new Set()
  server.on('session', (session) => {
    sessions.add(session)
    session.on('close', () => sessions.delete(session))
    session.on('error', () => {})
    session.socket?.on('error', () => {})
  })
  server.on('stream', (stream) => {
    stream.on('error', () => {})
    stream.respond({ ':status': 200 })
    const t = setInterval(() => {
      if (stream.destroyed || stream.closed) return clearInterval(t)
      stream.write(Buffer.alloc(4096))
    }, 5)
    stream.on('close', () => clearInterval(t))
  })
  await once(server.listen(0), 'listening')

  const url = `https://localhost:${server.address().port}/file`

  for (let round = 0; round < ROUNDS; round++) {
    const dispatcher = new Agent({
      connect: { rejectUnauthorized: false },
      allowH2: true
    }).compose(interceptors.redirect({ maxRedirections: 5 }))

    const timeout = 20 + Math.floor(Math.random() * 60)
    const results = []
    for (let i = 0; i < 6; i++) {
      results.push(request(url, {
        dispatcher,
        signal: AbortSignal.timeout(timeout)
      }).then(({ body }) => {
        body.on('error', () => {})
        body.resume()
        return once(body, 'close')
      }).catch(() => {}))
    }

    const killAt = Math.floor(Math.random() * 100)
    const killer = setTimeout(() => {
      for (const s of sessions) {
        const mode = Math.random()
        if (mode < 0.34) {
          s.socket?.end()
        } else if (mode < 0.67) {
          try { s.goaway(0) } catch {}
          setTimeout(() => s.socket?.end(), 5)
        } else {
          s.socket?.resetAndDestroy?.()
        }
      }
    }, killAt)

    await Promise.all(results)
    clearTimeout(killer)
    await new Promise((r) => setTimeout(r, 120))
    await dispatcher.destroy().catch(() => {})
  }
  console.log('fuzz done, no uncaught')
  server.close()
  for (const s of sessions) s.destroy()
}
main()

