        dispatcher,
        signal: AbortSignal.timeout(timeout)
      }).then(({ body }) => {
        body.on('error', () => {})
        body.resume()
        return once(body, 'close')
      }).catch(() => {}))
    }

    const killAt = Math.floor(Math.random() * 100)
    const killer = setTimeout(() => {
      const mode = Math.random()
      if (mode < 0.5) {
        for (const s of rawSockets) s.end()
      } else {
        for (const s of sessions) { try { s.goaway(0) } catch {} }
